#ifndef AGORA_SYSTEM_IMAGE_MASKS_H
#define AGORA_SYSTEM_IMAGE_MASKS_H

#include <stddef.h>

typedef struct {
	const char *name;		/* the glyph's own name, and the file it is drawn from */
	const unsigned char *coverage16;	/* 16x16, 256 bytes, row-major, top row first */
	const unsigned char *coverage24;	/* 24x24, 576 bytes: a toolbar's regular item, drawn 1:1 */
	const unsigned char *coverage32;	/* 32x32, 1024 bytes, the same shape at twice the size */
} AGSystemImageGlyph;


/* One row per glyph, sorted by name; the count is `AGSystemImageGlyphCount`. */
extern const AGSystemImageGlyph AGSystemImageGlyphs[];
extern const size_t AGSystemImageGlyphCount;


#endif /* AGORA_SYSTEM_IMAGE_MASKS_H */
